// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Temel ekonomi kavramları: arz-talep, piyasa, üretim (kolay).
const ozEconomics1Kolay = <(String, String, List<String>, String)>[
  ('Ekonomi biliminin varlık nedeni olarak gösterilen temel sorun aşağıdakilerden hangisidir?', 'Sınırsız ihtiyaçlar karşısında kaynakların kıt olması', ['Paranın icat edilmiş olması', 'Devletlerin harcamalarını karşılamak için halktan vergi toplaması', 'Nüfusun kentlerde yoğunlaşması'], 'Ekonomi, kıt kaynakların sınırsız ihtiyaçlar arasında nasıl dağıtılacağını inceler. Kıtlık olmasaydı seçim yapmaya gerek kalmazdı.'),
  ('Bir malın ekonomik anlamda "kıt" sayılması için hangi koşul yeterlidir?', 'Fiyatı sıfır olduğunda istenen miktarın mevcut miktarı aşması', ['Dünyada çok az ülkede üretilmesi', 'Üretiminin yüksek teknoloji gerektirmesi', 'Yalnızca zengin kişilerce ve yüksek fiyatlarla satın alınabilmesi'], 'Kıtlık mutlak azlık değil, göreli bir kavramdır: bedava olsaydı insanların isteyeceği miktar eldeki miktardan fazlaysa mal kıttır.'),
  ('İnsanın hoşnutsuzluk duyduğu ve giderilmesi istenen eksiklik duygusuna ekonomide ne ad verilir?', 'İhtiyaç', ['Fayda', 'Talep', 'Tasarruf'], 'İhtiyaç, giderildiğinde haz, giderilmediğinde acı veren eksiklik duygusudur. Talep ise ihtiyacın satın alma gücüyle desteklenmiş hâlidir.'),
  ('Bir seçim yapıldığında vazgeçilen en iyi alternatifin değerine ne ad verilir?', 'Fırsat maliyeti', ['Batık maliyet', 'Sabit maliyet', 'Marjinal hasılat'], 'Fırsat maliyeti, bir seçeneği tercih ederken feda edilen bir sonraki en iyi seçeneğin değeridir.'),
  ('"Bedava öğle yemeği diye bir şey yoktur." sözü ekonominin hangi temel fikrini anlatır?', 'Her seçimin bir fırsat maliyeti vardır.', ['Piyasada fiyatlar her zaman düşer.', 'Devlet her hizmeti ücretsiz sunmalıdır.', 'Tüketiciler her zaman ve her koşulda en ucuz malı seçer.'], 'Bir şey bize para ödemeden verilse bile onu üretmek için kullanılan kaynaklar başka bir yerde kullanılamaz; bu yüzden her seçimin bir bedeli vardır.'),
  ('Bir ekonominin mevcut kaynak ve teknolojiyle tam ve etkin kullanımda üretebileceği iki malın en büyük bileşimlerini gösteren eğri hangisidir?', 'Üretim imkânları eğrisi', ['Kayıtsızlık eğrisi', 'Lorenz eğrisi', 'Phillips eğrisi'], 'Üretim imkânları eğrisi (sınırı), kaynaklar tam ve etkin kullanıldığında ulaşılabilecek azami üretim bileşimlerini gösterir.'),
  ('Aşağıdakilerden hangisi bir ülkenin üretim imkânları eğrisini dışa doğru kaydırır?', 'Üretimde verimi artıran yeni bir teknolojinin yayılması', ['Fabrikaların önemli bir kısmının büyük bir deprem nedeniyle yıkılması', 'İşsizlik oranının artması', 'Tüketicilerin bir malı daha az tercih etmesi'], 'Teknolojik gelişme, kaynak artışı ya da işgücünün niteliğinin yükselmesi üretim kapasitesini artırarak eğriyi dışa kaydırır.'),
  ('Ekonomide insan ihtiyaçlarını karşılama özelliği olan, sınırlı miktarda bulunan ve bu yüzden bedeli olan şeylere ne ad verilir?', 'Ekonomik mal', ['Serbest mal', 'Kamusal ihtiyaç', 'Dışsallık'], 'Kıt olan ve elde edilmesi için bir bedel ödenmesi gereken mallar ekonomik maldır; bol bulunan ve bedelsiz olanlar serbest maldır.'),
  ('Aşağıdakilerden hangisi normal koşullarda serbest mala örnektir?', 'Açık havadaki solunan hava', ['Şişelenmiş kaynak suyu', 'Tüpe doldurulmuş oksijen', 'Çiftlikte yetiştirilen buğday'], 'Açık havadaki hava bol bulunur ve bedel ödemeden kullanılır. Tüpe ya da şişeye konan hava ve su ise emek ve sermaye gerektirdiği için ekonomik maldır.'),
  ('Buzdolabı, otomobil ve çamaşır makinesi gibi uzun süre kullanılan mallar nasıl adlandırılır?', 'Dayanıklı tüketim malları', ['Dayanıksız tüketim malları', 'Serbest mallar', 'Hammaddeler'], 'Bir kez kullanımda tükenmeyen, yıllarca hizmet veren mallar dayanıklı tüketim mallarıdır; gıda gibi tek kullanımda tükenenler dayanıksızdır.'),
  ('Klasik ekonomi yaklaşımında üretim faktörleri genellikle hangi dört başlıkta toplanır?', 'Emek, sermaye, doğal kaynak ve girişimci', ['Para, kredi, döviz ve altın', 'Arz, talep, fiyat ve miktar', 'Vergi, harcama, borç ve faiz'], 'Üretim için gerekli temel kaynaklar emek, sermaye, doğal kaynaklar (toprak) ve bunları bir araya getiren girişimcidir.'),
  ('Üretim faktörlerinden emeğin üretime katılmasının karşılığında aldığı gelire ne ad verilir?', 'Ücret', ['Rant', 'Kâr', 'Faiz'], 'Emeğin getirisi ücret, doğal kaynakların rant, sermayenin faiz, girişimcinin ise kârdır.'),
  ('Her ekonominin yanıtlamak zorunda olduğu üç temel soru hangisinde doğru verilmiştir?', 'Ne, nasıl ve kimin için üretilecek?', ['Ne zaman, nerede ve kaça satılacak?', 'Kim, neden ve hangi parayla ödeyecek?', 'Ne kadar vergi, borç ve faiz olacak?'], 'Kıtlık nedeniyle her toplum hangi malların, hangi yöntemle ve kimin için üretileceğine karar vermek zorundadır.'),
  ('Bir tekstil fabrikasında aşağıdakilerden hangisi sermaye faktörüne örnektir?', 'Dokuma tezgâhları', ['Fabrikada çalışan işçiler', 'Fabrikanın kurulduğu arazi', 'Fabrikayı kuran iş insanı'], 'Dokuma tezgâhları üretimde kullanılan insan yapımı araçlardır; işçiler emek, arazi doğal kaynak, kurucu ise girişimcidir.'),
  ('Aşağıdaki konulardan hangisi mikroekonominin inceleme alanına girer?', 'Bir pastanenin kek fiyatını belirlemesi', ['Ülkenin toplam işsizlik oranı', 'Ülkedeki genel fiyat düzeyinde yaşanan artış', 'Ülkenin yıllık büyüme hızı'], 'Mikroekonomi tek tek hane halkı, firma ve piyasaların davranışını inceler; toplam büyüklükler makroekonominin konusudur.'),
  ('Aşağıdakilerden hangisi makroekonominin inceleme alanına girer?', 'Bir ülkenin toplam üretim düzeyi', ['Domates piyasasındaki fiyat değişmesi', 'Bir firmanın kaç işçi çalıştıracağı', 'Bir tüketicinin elma ile armut arasındaki seçimi'], 'Makroekonomi ekonomiyi bir bütün olarak ele alır: toplam üretim, genel fiyat düzeyi, işsizlik ve büyüme gibi.'),
  ('Diğer koşullar sabitken bir malın fiyatı arttığında talep edilen miktarının azalmasını ifade eden ilke hangisidir?', 'Talep kanunu', ['Arz kanunu', 'Gresham kanunu', 'Say kanunu'], 'Talep kanununa göre fiyat ile talep edilen miktar arasında ters yönlü ilişki vardır.'),
  ('Talep eğrisinin sağdan aşağı doğru eğimli (negatif eğimli) olması neyi gösterir?', 'Fiyat düştükçe talep edilen miktarın arttığını', ['Fiyat arttıkça talep edilen miktarın da aynı yönde arttığını', 'Fiyatın miktardan bağımsız olduğunu', 'Gelir arttıkça fiyatın düştüğünü'], 'Negatif eğim, fiyat ile miktar arasındaki ters yönlü ilişkiyi yani talep kanununu yansıtır.'),
  ('Kahvenin fiyatı belirgin biçimde arttığında çayın talebinde ne olması beklenir?', 'Çayın talebi artar.', ['Çayın talebi azalır.', 'Çayın arzı azalır.', 'Çayın talebi hiç değişmez.'], 'Çay ve kahve birbirinin ikamesidir. Kahve pahalanınca tüketicilerin bir kısmı çaya yönelir ve çayın talep eğrisi sağa kayar.'),
  ('Birbirinin yerine kullanılabilen tereyağı ve margarin gibi mallara ne ad verilir?', 'İkame mallar', ['Tamamlayıcı mallar', 'Ara mallar', 'Kamusal mallar'], 'Aynı ihtiyacı karşılayabilen ve birinin yerine diğeri kullanılabilen mallar ikame mallardır.'),
  ('Gelir arttığında talebi de artan mallara ne ad verilir?', 'Normal mal', ['Düşük mal', 'Giffen malı', 'Serbest mal'], 'Normal mallarda gelir ile talep aynı yönde değişir; gelir esneklikleri pozitiftir.'),
  ('Bir malın kendi fiyatındaki değişme sonucu talep edilen miktarın değişmesi talep eğrisinde nasıl gösterilir?', 'Aynı talep eğrisi üzerinde hareketle', ['Talep eğrisinin bütünüyle sağa kaymasıyla', 'Talep eğrisinin sola kaymasıyla', 'Arz eğrisinin kaymasıyla'], 'Kendi fiyattaki değişme "talep edilen miktarda değişme"dir ve eğri boyunca bir noktadan diğerine geçişle gösterilir.'),
  ('Diğer koşullar sabitken bir malın fiyatı arttığında üreticilerin piyasaya sunmak istedikleri miktarın artmasını açıklayan ilke hangisidir?', 'Arz kanunu', ['Talep kanunu', 'Engel kanunu', 'Azalan fayda ilkesi'], 'Arz kanununa göre fiyat ile arz edilen miktar arasında aynı yönlü ilişki vardır.'),
  ('Arz eğrisi genellikle nasıl bir eğime sahiptir?', 'Pozitif, yani sağa doğru yükselen', ['Negatif, yani sağa doğru alçalan', 'Her zaman tamamen yatay', 'Her zaman tamamen dikey'], 'Fiyat yükseldikçe üretmek daha kârlı hâle gelir ve arz edilen miktar artar; bu da pozitif eğimli bir eğri verir.'),
  ('Aşağıdakilerden hangisi bir malın arz eğrisini sağa kaydırır?', 'Üretimde kullanılan hammaddenin ucuzlaması', ['Hammadde fiyatlarının artması', 'Malın kendi fiyatının düşmesi', 'Sektördeki firma sayısının iflaslar nedeniyle azalması'], 'Girdi maliyetlerinin düşmesi her fiyatta daha fazla üretimi kârlı kılar ve arzı artırır.'),
  ('Bir piyasada talep edilen miktarın arz edilen miktara eşit olduğu fiyata ne ad verilir?', 'Denge fiyatı', ['Tavan fiyat', 'Taban fiyat', 'Gölge fiyat'], 'Denge fiyatında alıcıların almak istediği miktar ile satıcıların satmak istediği miktar eşittir; piyasa temizlenir.'),
  ('Piyasa fiyatı denge fiyatının üzerinde olduğunda ne ortaya çıkar?', 'Arz fazlası', ['Talep fazlası', 'Kıtlık', 'Karaborsa'], 'Yüksek fiyatta üreticiler çok, tüketiciler az ister; satılamayan mallar arz fazlası (stok birikimi) oluşturur.'),
  ('Fiyat denge düzeyinin altında tutulursa piyasada ne gözlenir?', 'Talep fazlası', ['Arz fazlası', 'Stok birikimi', 'Üretim artışı'], 'Düşük fiyatta alıcılar çok, satıcılar az ister; talep edilen miktar arz edilen miktarı aşar ve kıtlık oluşur.'),
  ('Fiyatların piyasada alıcı ve satıcılara hangi malın ne kadar kıt olduğunu bildirmesi, fiyatın hangi işlevini anlatır?', 'Bilgi (sinyal) işlevini', ['Vergileme işlevini', 'Devlete vergi kazandırma (gelir) işlevini', 'Kur belirleme işlevini'], 'Yükselen fiyat malın kıtlaştığını gösterir; üreticileri üretmeye, tüketicileri tasarrufa yöneltir. Fiyatlar böylece bilgi taşır.'),
  ('Talep edilen miktardaki yüzde değişmenin fiyattaki yüzde değişmeye oranı hangi kavramı verir?', 'Talebin fiyat esnekliği', ['Talebin gelir esnekliğini veren ve gelirdeki değişmeye bakan oran', 'Arz esnekliğini gösteren ve üretici tepkisini ölçen oran', 'Marjinal tüketim eğilimini veren oran'], 'Fiyat esnekliği, tüketicilerin fiyat değişmelerine ne kadar duyarlı olduğunu ölçer.'),
  ('Aşağıdaki mallardan hangisinin talebinin fiyat esnekliğinin yüksek olması beklenir?', 'Bir markanın gazlı içeceği', ['Sofra tuzu', 'Kalp ilacı', 'Musluk suyu'], 'Belirli bir markanın ürünü için çok sayıda yakın ikame bulunur; fiyatı artınca tüketiciler diğer markalara geçer.'),
  ('Arz edilen miktardaki yüzde değişmenin fiyattaki yüzde değişmeye oranına ne ad verilir?', 'Arz esnekliği', ['Gelir esnekliği', 'Çapraz esneklik', 'İkame esnekliği'], 'Arz esnekliği, üreticilerin fiyat değişmelerine üretim miktarıyla ne ölçüde tepki verdiğini ölçer.'),
  ('Tüketicilerin bir mal için ödemeye razı oldukları en yüksek tutar ile fiilen ödedikleri tutar arasındaki farka ne ad verilir?', 'Tüketici rantı', ['Üretici rantı', 'Ekonomik rant', 'Ölü ağırlık kaybı'], 'Tüketici rantı, piyasadan alışveriş yapan tüketicilerin elde ettiği net kazancı ölçer.'),
  ('Devletin bir malın satılabileceği en yüksek fiyatı yasal olarak belirlemesine ne ad verilir?', 'Tavan fiyat', ['Taban fiyat', 'Denge fiyatı', 'Destekleme alımı'], 'Tavan fiyat, fiyatın belirli bir düzeyin üzerine çıkmasını yasaklayan bir sınırdır; genellikle tüketicileri korumak amacıyla konur.'),
  ('Tarımda üreticiyi korumak amacıyla devletin bir ürün için fiyatın altına düşemeyeceği bir sınır belirlemesi hangi uygulamadır?', 'Taban fiyat', ['Tavan fiyat', 'Fiyat farklılaştırması', 'Dampinge karşı vergi'], 'Taban fiyat, fiyatın belli bir düzeyin altına inmesini engeller; amacı genellikle üretici gelirini korumaktır.'),
  ('Bir maldan tüketilen son birimin toplam faydada yarattığı ek artışa ne ad verilir?', 'Marjinal fayda', ['Toplam fayda', 'Ortalama fayda', 'Marjinal maliyet'], 'Marjinal fayda, tüketimin bir birim artırılmasıyla toplam faydadaki değişmedir.'),
  ('Susamış birinin içtiği ilk bardak suyun ikinci ve üçüncü bardaktan daha fazla haz vermesi hangi ilkeyle açıklanır?', 'Azalan marjinal fayda', ['Artan ölçek getirisi', 'Arz kanunu', 'Karşılaştırmalı üstünlük'], 'Bir maldan art arda tüketildikçe her ek birimin sağladığı fayda giderek azalır.'),
  ('Belirli bir gelir ve fiyatlarla tüketicinin satın alabileceği iki malın tüm bileşimlerini gösteren doğruya ne ad verilir?', 'Bütçe doğrusu', ['Kayıtsızlık eğrisi', 'Talep eğrisi', 'Engel eğrisi'], 'Bütçe doğrusu, gelirin tamamı harcandığında alınabilecek mal bileşimlerini gösterir.'),
  ('Kullanılan girdi miktarları ile elde edilebilecek en yüksek çıktı arasındaki teknik ilişkiyi gösteren kavram hangisidir?', 'Üretim fonksiyonu', ['Talep fonksiyonu', 'Fayda fonksiyonu', 'Tüketim fonksiyonu'], 'Üretim fonksiyonu, belirli bir teknolojiyle girdilerden ne kadar çıktı elde edilebileceğini gösterir.'),
  ('Sabit bir tarlaya giderek daha fazla işçi eklendiğinde belli bir noktadan sonra her yeni işçinin üretime katkısının azalması hangi kanunla açıklanır?', 'Azalan verimler kanunu', ['Talep kanunu', 'Arz kanunu', 'Ölçek ekonomisi'], 'En az bir girdi sabitken değişken girdi artırıldıkça, bir noktadan sonra değişken girdinin marjinal ürünü azalır.'),
  ('Ekonomide firmanın en az bir üretim faktörünü değiştiremediği zaman aralığına ne ad verilir?', 'Kısa dönem', ['Uzun dönem', 'Hesap dönemi', 'Konjonktür dönemi'], 'Kısa dönemde fabrika binası gibi bazı girdiler sabittir; uzun dönemde ise tüm girdiler değiştirilebilir.'),
  ('Bir fabrikanın üretim miktarından bağımsız olarak ödediği aylık bina kirası hangi maliyet türüdür?', 'Sabit maliyet', ['Değişken maliyet', 'Marjinal maliyet', 'Fırsat geliri'], 'Üretim sıfır bile olsa ödenmesi gereken kira gibi giderler kısa dönemde sabit maliyettir.'),
  ('Bir mobilya atölyesinde üretim arttıkça artan kereste harcaması hangi maliyet türüne girer?', 'Değişken maliyet', ['Sabit maliyet', 'Batık maliyet', 'Örtük maliyet'], 'Üretim miktarıyla birlikte değişen hammadde, enerji ve işçilik gibi giderler değişken maliyettir.'),
  ('Üretim ölçeği büyüdükçe birim başına uzun dönem ortalama maliyetin düşmesine ne ad verilir?', 'Ölçek ekonomisi', ['Ölçek eksi ekonomisi', 'Azalan verimler', 'Fiyat katılığı'], 'Büyük ölçekli üretimde uzmanlaşma, toplu alım ve teknolojinin tam kullanımı birim maliyeti düşürebilir.'),
  ('Aşağıdakilerden hangisi tam rekabet piyasasının özelliklerinden biridir?', 'Homojen ürün', ['Tek satıcının bulunması', 'Piyasaya girişte yasal engellerin olması', 'Firmaların fiyatı kendisinin belirlemesi'], 'Tam rekabette çok sayıda alıcı ve satıcı, homojen ürün, serbest giriş-çıkış ve tam bilgi vardır.'),
  ('Tam rekabet piyasasında bir firma ürününü piyasa fiyatının biraz üzerinde satmaya çalışırsa ne olur?', 'Müşterilerinin tamamını kaybeder.', ['Satışları hiç değişmez, yalnızca kârı artar.', 'Diğer firmalar da fiyatlarını yükseltmek zorunda kalır.', 'Devlet fiyat farkını firmaya öder.'], 'Ürünler homojen ve bilgi tam olduğundan alıcılar hemen daha ucuz satan diğer firmalara yönelir.'),
  ('Bir malın tek satıcısının bulunduğu ve yakın ikamesinin olmadığı piyasa türü hangisidir?', 'Tekel', ['Tam rekabet', 'Oligopol', 'Monopolcü rekabet'], 'Tekelde piyasada tek bir firma vardır ve piyasa talep eğrisinin tamamı bu firmanın talep eğrisidir.'),
  ('Bir firmanın aynı malı maliyet farkı olmaksızın farklı alıcılara farklı fiyatlarla satmasına ne ad verilir?', 'Fiyat farklılaştırması', ['Fiyat tavanı', 'Damping vergisi', 'Fiyat istikrarı'], 'Fiyat farklılaştırması, ödeme isteği farklı tüketici gruplarından farklı fiyatlar alınmasıdır.'),
  ('Az sayıda büyük firmanın piyasaya hâkim olduğu ve firmaların birbirinin kararlarını dikkate aldığı piyasa türü hangisidir?', 'Oligopol', ['Monopolcü rekabet', 'Tam rekabet', 'Monopson'], 'Oligopolde firmalar karşılıklı bağımlıdır; her biri rakiplerinin tepkisini hesaba katarak fiyat ve üretim kararı verir.'),
  ('Aşağıdaki piyasalardan hangisi oligopol yapısına en uygundur?', 'Birkaç büyük operatörün bulunduğu mobil telefon hizmetleri', ['Yüzlerce çiftçinin sattığı patates', 'Bir semtteki çok sayıda simitçi', 'Bir kasabadaki tek elektrik dağıtım şirketinin sunduğu hizmet'], 'Mobil hizmetlerde az sayıda büyük firma vardır, giriş için yüksek yatırım ve lisans gerekir; firmalar birbirinin kararını izler.'),
  ('Bir ekonomik faaliyetin, piyasada fiyatlanmadan üçüncü kişileri etkilemesine ne ad verilir?', 'Dışsallık', ['Esneklik', 'Kıtlık', 'Batık maliyet'], 'Dışsallık, bir işlemin alıcı ve satıcı dışındaki kişilere yansıyan ve fiyata dâhil edilmeyen maliyet ya da faydasıdır.'),
  ('Aşağıdakilerden hangisi saf kamusal mala en iyi örnektir?', 'Ulusal savunma', ['Bir restorandaki yemek', 'Ücretli bir otoyolda yolculuk', 'Kişisel bilgisayar'], 'Ülke savunmasından herkes aynı anda yararlanır ve vergi ödemeyen biri bu korumadan dışlanamaz.'),
  ('Bir mahallede herkesin yararlanacağı bir parkın yapımı için bağış toplanırken bazı sakinlerin "Nasılsa başkaları öder, ben de yararlanırım." diye düşünmesi hangi davranışa örnektir?', 'Bedavacılık', ['Ahlaki tehlike', 'Fiyat farklılaştırması', 'Spekülasyon'], 'Bedavacı, maliyete katlanmadan başkalarının sağladığı faydadan yararlanmayı umar.'),
  ('Bireylerin kendi çıkarlarını gözetirken farkında olmadan toplumun yararına hizmet ettiğini anlatan "görünmez el" benzetmesi hangi düşünüre aittir?', 'Adam Smith', ['Karl Marx', 'David Ricardo', 'Thomas Malthus'], 'Adam Smith bu benzetmeyi 1776\'da yayımlanan "Ulusların Zenginliği" adlı eserinde kullanmıştır.'),
  ('Döngüsel akım modelinde hane halkları firmalara hangi piyasada üretim faktörü sunar?', 'Faktör piyasasında', ['Mal piyasasında', 'Döviz piyasasında', 'Hisse senedi borsasında'], 'Hane halkları emek, sermaye ve toprak gibi faktörleri faktör piyasasında firmalara sunar ve karşılığında ücret, faiz, rant, kâr alır.'),
  ('Bir ülkenin sınırları içinde belirli bir dönemde üretilen tüm nihai mal ve hizmetlerin piyasa değerine ne ad verilir?', 'Gayrisafi yurt içi hasıla', ['Kişi başına düşen tasarruf', 'Dış ticaret dengesi', 'Toplam vergi geliri'], 'GSYH, bir ülkenin ekonomik faaliyet hacmini ölçen temel göstergedir; yalnızca nihai mallar sayılır.'),
  ('Bir otomobil fabrikasında yapılan montaj hangi sektöre ait bir faaliyettir?', 'Sanayi (ikincil sektör)', ['Tarım (birincil sektör)', 'Hizmetler (üçüncül sektör)', 'Hanehalkı üretimi'], 'Hammadde ve ara malların işlenerek yeni ürünlere dönüştürüldüğü imalat faaliyetleri ikincil sektördür.'),
  ('"Ekonomi" sözcüğünün kökeni olan Yunanca "oikonomia" ilk anlamıyla neyi ifade eder?', 'Ev yönetimini', ['Devletin savaş harcamalarını düzenleme sanatını', 'Deniz ticaretinin kurallarını', 'Tapınak vergilerinin toplanmasını'], 'Oikos (ev) ve nomos (yasa, düzen) sözcüklerinden türeyen oikonomia, hane yönetimi anlamına gelir.'),
  ('Aşağıdakilerden hangisi bir ihtiyacın değil, ihtiyacı karşılayan bir malın örneğidir?', 'Ekmek', ['Açlık duygusu', 'Barınma isteği', 'Korunma gereksinimi'], 'Açlık bir ihtiyaçtır; ekmek ise bu ihtiyacı karşılayan maldır.'),
  ('Zaman kavramı ekonomi açısından neden kıt bir kaynak olarak görülür?', 'Herkesin günü 24 saatle sınırlıdır.', ['Saatlerin fiyatı devlet tarafından belirlendiği için', 'Zaman satın alınıp depolanabildiği için', 'Yalnızca çalışanlar için önem taşıdığı için'], 'Bir saati bir işe ayırmak, o saati başka bir işe ayıramamak demektir; bu nedenle zaman da seçim gerektiren kıt bir kaynaktır.'),
  ('Bir öğrenci akşamını sınava çalışmak yerine dizi izleyerek geçirirse fırsat maliyeti nedir?', 'Ders çalışarak elde edeceği kazanç', ['Dizinin yapım maliyeti', 'Televizyonun satın alma fiyatı', 'Evin elektrik faturasının tamamı'], 'Fırsat maliyeti, seçilen dizi izleme yerine vazgeçilen en iyi alternatif olan çalışmanın getirisidir.'),
  ('Bir çiftçi tarlasının tamamına mısır ekerse aynı yıl hangi şeyden vazgeçmiş olur?', 'Tarlada başka ürün yetiştirme olanağından', ['Mısırın satış gelirinden', 'Tarlanın mülkiyetinden', 'Ertesi yıl ekim yapma hakkından'], 'Toprak bir anda tek bir amaçla kullanılabilir; mısır ekmenin fırsat maliyeti, yetiştirilemeyen en iyi alternatif üründür.'),
  ('Üretim imkânları eğrisi üzerindeki bir noktadan diğerine geçmek neyi gerektirir?', 'Bir malın üretimini azaltmayı', ['Kaynak miktarını iki katına çıkarmayı', 'Yeni bir teknoloji icat etmeyi', 'Tüketimi tamamen durdurmayı'], 'Eğri üzerinde kaynaklar tam kullanıldığından bir malı artırmak için diğerinden vazgeçmek gerekir.'),
  ('Büyük bir deprem bir ülkenin fabrikalarının önemli bir bölümünü yıkarsa üretim imkânları eğrisine ne olur?', 'İçe doğru kayar.', ['Dışa doğru kayar ve büyür.', 'Hiç değişmez, yalnızca fiyatlar artar.', 'Eğri yerine tek bir nokta oluşur.'], 'Sermaye stokunun azalması üretim kapasitesini düşürür ve eğri içe kayar.'),
  ('Aşağıdakilerden hangisi bir hizmettir?', 'Diş tedavisi', ['Diş fırçası', 'Diş macunu', 'Ağız suyu şişesi'], 'Diş tedavisi bir uzmanın emeğiyle sunulan soyut bir faaliyettir; diğerleri somut mallardır.'),
  ('Ekmek, süt ve meyve gibi bir ya da birkaç kullanımda tükenen mallara ne ad verilir?', 'Dayanıksız tüketim malları', ['Dayanıklı tüketim malları', 'Yatırım malları', 'Kamusal mallar'], 'Kısa sürede ya da tek kullanımda tükenen mallar dayanıksız tüketim mallarıdır.'),
  ('Üretim faktörlerinden "doğal kaynaklar" kapsamında aşağıdakilerden hangisi yer alır?', 'Maden yatakları', ['Fabrika binaları', 'İşçilerin becerileri', 'Yönetim kararları'], 'Toprak, su, orman ve madenler gibi doğada hazır bulunan kaynaklar doğal kaynak faktörüdür.'),
  ('Piyasa ekonomisinde tüketicilerin hangi malların üretileceğini harcamalarıyla belirlemesine ne denir?', 'Tüketici egemenliği', ['Devlet tekeli', 'Üretici kartelleşmesi', 'Geleneksel paylaşım'], 'Tüketiciler parayla "oy verir"; çok talep gören mallar kârlı olur ve daha çok üretilir.'),
  ('"Geçen yıl ülkede işsizlik oranı arttı." ifadesi hangi türdendir?', 'Pozitif ifade', ['Normatif ifade', 'Değer yargısı', 'Siyasi öneri'], 'Bu ifade bir olguyu anlatır ve verilerle doğrulanabilir; bu yüzden pozitiftir.'),
  ('Bir ayakkabı fabrikasında yeni ve daha hızlı makinelerin kullanılmaya başlanması ayakkabı arzını nasıl etkiler?', 'Arz artar.', ['Arz azalır.', 'Talep azalır.', 'Arz değişmez, yalnızca fiyat artar.'], 'Teknolojik gelişme birim maliyeti düşürür ve her fiyatta daha fazla üretimi mümkün kılar.'),
  ('Ekmek sektörüne çok sayıda yeni fırın girmesi piyasa arzını nasıl etkiler?', 'Arz eğrisi sağa kayar.', ['Arz eğrisi sola kayar.', 'Talep eğrisi sola kayar.', 'Arz eğrisi dikey hâle gelir.'], 'Satıcı sayısının artması her fiyatta piyasaya sunulan toplam miktarı artırır.'),
  ('Bir piyasada alıcıların ve satıcıların karşılaşarak fiyat belirlemesi hangi kavramla ifade edilir?', 'Piyasa mekanizması', ['Merkezî planlama', 'Kotalama sistemi', 'Karne uygulaması'], 'Piyasa mekanizması, arz ve talebin etkileşimiyle fiyat ve miktarın kendiliğinden belirlenmesidir.'),
  ('Talebin fiyat esnekliği 1\'den büyük olan mallar için hangi nitelendirme yapılır?', 'Esnek talep', ['İnelastik talep', 'Türetilmiş talep', 'Birim esnek talep'], 'Esneklik 1\'den büyükse talep edilen miktar fiyattan daha büyük oranda değişir; talep esnektir.'),
  ('Talep eğrisi tamamen yatay olan bir malın fiyat esnekliği nasıl adlandırılır?', 'Tam esnek (sonsuz)', ['Tam inelastik (sıfır)', 'Birim esnek', 'Negatif esnek'], 'Yatay talep eğrisinde fiyat azıcık artarsa talep tamamen ortadan kalkar; bu tam esnek taleptir.'),
  ('Bir kalemin fiyatı 10 TL\'den 12 TL\'ye çıkmış, satışlar 100 adetten 90 adede düşmüştür. Toplam hasılat nasıl değişmiştir?', '1.000 TL\'den 1.080 TL\'ye çıkmıştır.', ['1.000 TL\'den 900 TL\'ye düşmüştür.', 'Değişmemiştir.', '1.200 TL\'den 1.080 TL\'ye düşmüştür.'], 'Önce 10 × 100 = 1.000 TL, sonra 12 × 90 = 1.080 TL\'dir. Hasılat arttığına göre bu aralıkta talep inelastiktir.'),
  ('Satıcıların bir malı satmaya razı oldukları en düşük fiyat ile aldıkları fiyat arasındaki farka ne ad verilir?', 'Üretici rantı', ['Tüketici rantı', 'Ölü ağırlık kaybı', 'Muhasebe kârı'], 'Üretici rantı, satıcıların piyasaya katılmaktan elde ettiği net kazançtır.'),
  ('Devletin buğday için belirlediği taban fiyat piyasa fiyatının üzerindeyse devlet artan ürünü genellikle ne yapar?', 'Destekleme alımıyla satın alır.', ['İmha edilmesini zorunlu kılar.', 'Tüketicilere zorla dağıtır.', 'Fiyatı hemen yarıya indirir.'], 'Taban fiyat arz fazlası yaratır; devlet bu fazlayı alım kurumları aracılığıyla satın alarak fiyatı korur.'),
  ('Bir mala birim başına vergi konması o malın satılan miktarını genellikle nasıl etkiler?', 'Azaltır.', ['Artırır.', 'Hiç etkilemez.', 'İki katına çıkarır.'], 'Vergi alıcıların ödediği fiyatı yükseltir, satıcıların eline geçeni düşürür; bu yüzden işlem miktarı azalır.'),
  ('Bir tüketicinin bir maldan tükettiği tüm birimlerden sağladığı toplam tatmine ne ad verilir?', 'Toplam fayda', ['Marjinal fayda', 'Ortalama maliyet', 'Tüketici bütçesi'], 'Toplam fayda, tüketilen birimlerin marjinal faydalarının toplamıdır.'),
  ('Tüketicinin bütçe doğrusunun dışında kalan bir mal bileşimi için ne söylenebilir?', 'Mevcut gelirle satın alınamaz.', ['Gelirin tamamı harcanmadan satın alınabilir.', 'Tüketiciye en düşük faydayı verir.', 'Fiyatlar sıfır olduğunda bile alınamaz.'], 'Bütçe doğrusunun dışı, gelirin yetmediği bileşimleri gösterir; içi ise gelirin bir kısmının harcanmadığı bileşimlerdir.'),
  ('Bir firmanın toplam üretiminin kullanılan işçi sayısına bölünmesiyle ne elde edilir?', 'Emeğin ortalama ürünü', ['Emeğin marjinal ürünü', 'Ortalama sabit maliyet', 'Marjinal hasılat'], 'Ortalama ürün, işçi başına düşen üretimdir.'),
  ('Bir birim daha üretmenin toplam maliyette yol açtığı artışa ne ad verilir?', 'Marjinal maliyet', ['Ortalama sabit maliyet', 'Batık maliyet', 'Toplam sabit maliyet'], 'Marjinal maliyet, üretimdeki bir birimlik artışın toplam maliyete eklediği tutardır.'),
  ('Bir firmanın tüm girdilerini iki katına çıkardığında üretiminin de tam iki katına çıkması neyi gösterir?', 'Ölçeğe göre sabit getiri', ['Ölçeğe göre artan getiri', 'Ölçeğe göre azalan getiri', 'Azalan verimler kanunu'], 'Çıktı girdilerle aynı oranda artıyorsa ölçeğe göre getiri sabittir.'),
  ('Toplam hasılattan yalnızca açık (parasal) maliyetler çıkarıldığında elde edilen kâra ne ad verilir?', 'Muhasebe kârı', ['Ekonomik kâr', 'Normal kâr', 'Tekel rantı'], 'Muhasebe kârı örtük maliyetleri dikkate almaz; bu yüzden genellikle ekonomik kârdan büyüktür.'),
  ('Bir firmanın toplam hasılatı 80.000 TL, toplam maliyeti 65.000 TL\'dir. Kârı kaç TL\'dir?', '15.000 TL', ['145.000 TL', '65.000 TL', '80.000 TL'], 'Kâr = toplam hasılat − toplam maliyet = 80.000 − 65.000 = 15.000 TL\'dir.'),
  ('Tam rekabet piyasasında firmaların piyasaya girişi ve çıkışı için hangisi geçerlidir?', 'Serbesttir.', ['Devlet iznine bağlıdır.', 'Yalnızca patent sahiplerine açıktır.', 'Tamamen yasaktır.'], 'Tam rekabette giriş ve çıkışın önünde yasal ya da ekonomik engel bulunmaz.'),
  ('Tekelci bir firma için piyasa talep eğrisi ile firmanın talep eğrisi arasındaki ilişki nedir?', 'Aynı eğridir.', ['Firmanın eğrisi yataydır.', 'Firmanın eğrisi dikeydir.', 'Birbirine diktir.'], 'Piyasada tek satıcı olduğundan piyasa talebinin tamamı tekelin talebidir.'),
  ('Bir piyasada yalnızca iki satıcının bulunmasına ne ad verilir?', 'Düopol', ['Monopson', 'Monopol', 'Tam rekabet'], 'Düopol, oligopolün yalnızca iki firmadan oluşan özel bir türüdür.'),
  ('Aşağıdakilerden hangisi tüketimde rakip ve dışlanabilir olduğu için özel mala örnektir?', 'Bir dilim pasta', ['Deniz feneri ışığı', 'Ulusal savunma', 'Hava durumu yayını'], 'Pastayı bir kişi yerse diğeri aynı dilimi yiyemez ve parası ödenmeden alınamaz; bu özel malın özellikleridir.'),
  ('Ekonomide kaynakların israf edilmeden en verimli biçimde kullanılmasına ne ad verilir?', 'Etkinlik', ['Kıtlık', 'Enflasyon', 'Dışsallık'], 'Etkinlik, kıt kaynaklardan toplumun en yüksek faydayı elde etmesidir.'),
  ('Basit döngüsel akım modelindeki iki temel ekonomik birim hangileridir?', 'Hane halkları ve firmalar', ['Bankalar ve borsalar', 'Devlet ve yabancılar', 'Sendikalar ve dernekler'], 'En basit modelde hane halkları faktör sunup mal satın alır, firmalar faktör kullanıp mal üretir.'),
  ('Bir mağazanın "İkinci ürün yarı fiyatına" kampanyası tüketiciler için neyi değiştirir?', 'İkinci ürünü almanın marjinal maliyetini', ['Birinci ürünün kalitesini', 'Mağazanın sabit maliyetlerini', 'Tüketicinin gelirini doğrudan'], 'Kampanya ek bir ürün almanın maliyetini düşürür; insanlar marjinal maliyetteki değişikliğe tepki verir.'),
  ('Bir şehirlerarası otobüs firmasının yolcu taşıması hangi sektöre girer?', 'Hizmetler', ['Sanayi', 'Tarım', 'Madencilik'], 'Ulaştırma somut mal üretmeyen bir faaliyettir ve hizmetler sektöründe yer alır.'),
  ('Bir ekonomide aynı kaynaklarla daha fazla üretim yapılabilmesine ne ad verilir?', 'Verimlilik artışı', ['Kıtlık artışı', 'Talep daralması', 'Fiyat tavanı'], 'Verimlilik, girdi başına çıktıdır; aynı girdiyle daha çok çıktı verimliliğin arttığını gösterir.'),
  ('Bir kişinin ya da bölgenin belirli bir işte yoğunlaşıp o işi daha iyi yapar hâle gelmesine ne ad verilir?', 'Uzmanlaşma', ['Kıtlık', 'Tekelleşme', 'Kayıtsızlık'], 'Uzmanlaşma, beceri ve bilgiyi belirli bir alanda derinleştirerek verimliliği artırır.'),
  ('Bir ailenin bütçesi sınırlı olduğu için tatil ile yeni buzdolabı arasında seçim yapmak zorunda kalması hangi temel ekonomik gerçeği yansıtır?', 'Kıtlığı', ['Bolluğu', 'Tekelleşmeyi', 'Dışsallığı'], 'Gelir ihtiyaçların tamamına yetmediğinde seçim yapmak gerekir; bu kıtlığın günlük yaşamdaki yansımasıdır.'),
  ('Aşağıdakilerden hangisi temel (birincil) ihtiyaçlar arasında yer alır?', 'Beslenme', ['Lüks otomobil', 'Yurt dışı gezisi', 'Mücevher'], 'Beslenme, barınma ve giyinme yaşamı sürdürmek için zorunlu olan temel ihtiyaçlardır.'),
  ('Bir belediyenin aynı arsaya ya okul ya da otopark yapabildiği durumda okul yapmanın fırsat maliyeti nedir?', 'Yapılamayan otopark', ['Okulun inşaat maliyeti', 'Öğretmen maaşları', 'Okulun elektrik giderleri'], 'Fırsat maliyeti, seçilen seçenek nedeniyle vazgeçilen en iyi alternatiftir; burada bu otoparktır.'),
  ('Üretim imkânları eğrisi üzerindeki tüm noktalar için ortak özellik nedir?', 'Kaynaklar tam ve etkin kullanılır.', ['Kaynakların yarısı atıldır.', 'Yalnızca tek bir mal üretilir.', 'Üretim teknolojisi sınırının dışındadır.'], 'Eğri üzerindeki her bileşim, mevcut kaynak ve teknolojiyle ulaşılabilecek en yüksek üretimi gösterir.'),
  ('Bir inşaatta çalışan duvar ustası hangi üretim faktörüne örnektir?', 'Emek', ['Sermaye', 'Doğal kaynak', 'Girişimci'], 'Üretime katılan insanın bedensel ve zihinsel çabası emektir.'),
  ('Üretim faktörlerinden sermayenin üretime katılmasının karşılığı olarak elde edilen gelire ne ad verilir?', 'Faiz', ['Ücret', 'Rant', 'Kâr'], 'Klasik dağılımda sermayenin getirisi faiz olarak adlandırılır.'),
  ('Bir ekonomide "nasıl üretilecek?" sorusu hangi konuyla ilgilidir?', 'Üretim yöntemi ve teknolojinin seçimi', ['Malların kime dağıtılacağı', 'Hangi malların üretileceği', 'Malların hangi ülkeye satılacağı'], 'Nasıl sorusu, hangi faktör bileşimi ve teknolojiyle üretim yapılacağını, örneğin emek mi makine mi yoğun yöntem seçileceğini kapsar.'),
  ('Bir futbol takımının şampiyon olmasıyla takım formalarının daha çok aranır hâle gelmesi talebi etkileyen hangi etkene örnektir?', 'Zevk ve tercihler', ['Girdi fiyatları', 'Üretim teknolojisi', 'Üretici sayısı'], 'Tüketicilerin bir mala yönelik ilgisinin artması talep eğrisini sağa kaydırır.'),
  ('Denge fiyatında piyasada aşağıdakilerden hangisi bulunmaz?', 'Arz ya da talep fazlası', ['Alıcılar', 'Satıcılar', 'El değiştiren mal'], 'Dengede talep edilen ve arz edilen miktarlar eşittir; fazla ya da eksik oluşmaz.'),
  ('Fiyat değiştiğinde talep edilen miktarın aynı oranda değişmesi hangi esneklik türüdür?', 'Birim esnek', ['Tam esnek', 'Tam inelastik', 'İnelastik'], 'Miktar ve fiyattaki yüzde değişmeler eşitse esneklik 1\'dir; buna birim esneklik denir.'),
  ('Arz esnekliği 1\'den küçük olan bir mal için ne söylenir?', 'Arzı inelastiktir.', ['Arzı esnektir.', 'Arzı birim esnektir.', 'Arzı negatif eğimlidir.'], 'Arz edilen miktar fiyattan daha düşük oranda değişiyorsa arz inelastiktir.'),
  ('Devletin bir malın üretimini teşvik etmek için üreticilere yaptığı ödemeye ne ad verilir?', 'Sübvansiyon', ['Vergi', 'Ceza', 'Kota'], 'Sübvansiyon üretim maliyetini düşürerek arzı artırır.'),
  ('Bir maldan bir birim daha tüketmek toplam faydayı azaltıyorsa o birimin marjinal faydası için ne söylenir?', 'Negatiftir.', ['Pozitiftir.', 'Sıfırdır.', 'Sonsuzdur.'], 'Toplam faydanın düşmesi, son birimin olumsuz katkı yaptığını yani marjinal faydanın negatif olduğunu gösterir.'),
  ('Bir atölyede 2 işçiyle günde 40 sandalye, 3 işçiyle 54 sandalye üretiliyor. Üçüncü işçinin marjinal ürünü kaçtır?', '14', ['18', '54', '20'], 'Marjinal ürün = 54 − 40 = 14 sandalyedir.'),
  ('Büyük süpermarket zincirlerinin küçük bakkallardan daha ucuza mal alabilmesi neyin sonucudur?', 'Ölçek ekonomisinin', ['Azalan verimlerin', 'Negatif dışsallığın', 'Fiyat tavanının'], 'Toplu alım, büyük firmaların birim maliyetini düşüren bir ölçek ekonomisi kaynağıdır.'),
  ('Ekonomik kârın pozitif olması ne anlama gelir?', 'Tüm fırsat maliyetlerinin üzerinde kazanç sağlanmıştır.', ['Firma zarar etmektedir.', 'Firma yalnızca açık maliyetlerini karşılamaktadır.', 'Firmanın hasılatı sıfırdır.'], 'Pozitif ekonomik kâr, kaynakların en iyi alternatif kullanımından daha fazla kazanç getirdiğini gösterir.'),
  ('Tam rekabet piyasasında satıcı sayısı için hangisi doğrudur?', 'Çok sayıda satıcı vardır.', ['Tek satıcı vardır.', 'İki satıcı vardır.', 'Az sayıda büyük satıcı vardır.'], 'Çok sayıda küçük satıcı bulunması, hiçbirinin tek başına fiyatı etkileyememesini sağlar.'),
  ('Tekelde fiyatı kim belirler?', 'Tekelci firma', ['Çok sayıda rakip firma', 'Yalnızca tüketiciler', 'Piyasadaki tüm firmalar birlikte'], 'Tekel fiyat belirleyicidir; ancak fiyatı belirlerken talep eğrisiyle sınırlıdır.'),
  ('Kartellerin çoğu ülkede yasaklanmasının temel nedeni nedir?', 'Rekabeti ortadan kaldırıp fiyatları yükseltmeleri', ['Üretimi aşırı artırmaları', 'Fiyatları maliyetin altına indirmeleri', 'Tüketicilere bedava mal dağıtmaları'], 'Kartel üyeleri birlikte üretimi kısarak tekel gibi davranır; bu da tüketicilerin zararınadır.'),
  ('Bir hastanede doktorların farklı uzmanlık alanlarına ayrılması ekonomik olarak hangi kavramla ilgilidir?', 'Uzmanlaşma', ['Kıtlık', 'Kayıtsızlık', 'Ters seçim'], 'Her doktorun belirli bir alana yoğunlaşması bilgi ve beceri derinliğini artırır.'),
  ('Bir malın bedelini ödemeyenlerin o maldan yararlanmasının engellenememesine ne ad verilir?', 'Dışlanamazlık', ['Rakiplik', 'Dayanıklılık', 'Homojenlik'], 'Dışlanamaz mallarda ödeme yapmayanları tüketimden alıkoymak mümkün değildir ya da çok pahalıdır.'),
  ('Bir fabrika aynı miktarda ürünü daha az hammadde kullanarak üretmeye başlarsa ne artmış olur?', 'Üretim etkinliği', ['Kıtlık', 'Batık maliyet', 'Ters seçim'], 'Aynı çıktının daha az girdiyle elde edilmesi kaynakların daha etkin kullanıldığını gösterir.'),
  ('Döngüsel akım modelinde firmaların hane halklarına ödediği ücret, faiz, rant ve kâr toplamına ne ad verilir?', 'Faktör gelirleri', ['Tüketim harcamaları', 'Ara mal giderleri', 'Vergi gelirleri'], 'Üretim faktörlerini sağlayan hane halkları bu faktörlerin karşılığını gelir olarak alır.'),
  ('Arz kavramı en doğru biçimde nasıl tanımlanır?', 'Satıcıların çeşitli fiyatlarda satmaya hazır oldukları miktarlar', ['Tüketicilerin satın almak istedikleri miktarlar', 'Devletin depolarında tuttuğu mal miktarı', 'Bir malın üretim maliyeti'], 'Arz, belirli bir dönemde farklı fiyat düzeylerinde üreticilerin piyasaya sunmaya istekli ve muktedir oldukları miktarlardır.'),
  ('Bir malın fiyatı yasal olarak denge fiyatının altında sabitlenirse piyasada en olası gözlem hangisidir?', 'Raflarda malın bulunamaması', ['Depoların dolup taşması', 'Satıcıların fiyat indirimi yapması', 'Üretimin artması'], 'Düşük fiyatta talep edilen miktar arzı aşar; mal kıtlaşır ve raflar boşalır.'),
  ('Tüketici rantı ile üretici rantının toplamı en çok hangi durumda en yüksek olur?', 'Rekabetçi piyasa dengesinde', ['Bağlayıcı tavan fiyat uygulandığında', 'Yüksek bir vergi konduğunda', 'Tekel fiyatı uygulandığında'], 'Müdahalesiz rekabetçi dengede tüm karşılıklı yararlı işlemler gerçekleşir; toplam artık en yüksektir.'),
  ('Tüketici dengesine ulaşan bir kişi için hangisi doğrudur?', 'Bütçesiyle elde edebileceği en yüksek faydayı sağlar.', ['Gelirinin tamamını tasarruf eder.', 'Her maldan eşit miktar alır.', 'En pahalı malı seçer.'], 'Tüketici dengesi, bütçe kısıtı altında faydanın en yüksek düzeyde olduğu noktadır.'),
  ('Kısa dönemde bir fabrika için genellikle hangi girdi sabit kabul edilir?', 'Fabrika binası', ['Hammadde', 'Elektrik', 'Geçici işçiler'], 'Bina ve büyük makineler kısa sürede değiştirilemediği için kısa dönemde sabit girdilerdir.'),
  ('Üretim düzeyi 200 birim olan bir atölyenin bütün giderleri toplamı 8.000 TL\'dir. Birim başına düşen maliyet kaç TL\'dir?', '40 TL', ['16 TL', '1.600 TL', '400 TL'], 'Ortalama toplam maliyet = 8.000 / 200 = 40 TL\'dir.'),
  ('Ekonomide firmaların temel amacının genellikle hangisi olduğu varsayılır?', 'Kârı en yükseğe çıkarmak', ['Maliyeti en yükseğe çıkarmak', 'Fiyatı sıfıra indirmek', 'Satışları en aza indirmek'], 'Standart firma kuramında firmaların kâr maksimizasyonu peşinde olduğu varsayılır.'),
  ('Tam rekabetteki bir firma için piyasa fiyatı 50 TL\'dir. Firma 10 birim daha fazla satarsa toplam hasılatı kaç TL artar?', '500 TL', ['50 TL', '5.000 TL', '60 TL'], 'Fiyat sabit olduğundan her ek birim 50 TL getirir: 10 × 50 = 500 TL.'),
  ('Bir piyasaya yeni firmaların girmesini zorlaştıran etkenlere genel olarak ne ad verilir?', 'Giriş engelleri', ['Dışsallıklar', 'Ara mallar', 'Teşvikler'], 'Patent, lisans, yüksek kuruluş maliyeti ve kilit kaynak denetimi giriş engellerine örnektir.'),
  ('Oyun teorisi ekonomide en çok hangi piyasa türünü incelemek için kullanılır?', 'Oligopol', ['Tam rekabet', 'Serbest mal piyasası', 'Kamusal mal piyasası'], 'Oligopolde firmalar karşılıklı bağımlı olduğundan stratejik etkileşimi çözümlemek için oyun teorisi kullanılır.'),
  ('Emek piyasasında ücret genellikle hangi iki gücün etkileşimiyle belirlenir?', 'Emek arzı ve emek talebi', ['Mal arzı ve döviz kuru', 'Vergi ve sübvansiyon', 'İthalat ve ihracat'], 'Ücret, işçilerin sunduğu emek ile firmaların talep ettiği emeğin karşılaştığı noktada oluşur.'),
  ('Bir deniz fenerinin geleneksel olarak kamusal mal örneği gösterilmesinin nedeni nedir?', 'Işığından herkesin ücretsiz yararlanması', ['Fenerin çok pahalı bir bina olması', 'Fenerin yalnızca tek bir gemiye hizmet etmesi', 'Fenerin hiç bakım gerektirmemesi'], 'Fener ışığını gören her gemi yararlanır ve ödeme yapmayan gemiler dışlanamaz.'),
  ('Bir sigorta şirketinin, sigortalının kendi riskini şirketten daha iyi bilmesinden doğan sorunu azaltmak için sağlık taraması istemesi hangi soruna karşı bir önlemdir?', 'Ters seçim', ['Bedavacılık', 'Pozitif dışsallık', 'Fiyat katılığı'], 'Tarama, sözleşme öncesindeki bilgi farkını azaltarak riskli kişilerin orantısız biçimde sigortalanmasını önlemeye çalışır.'),
  ('Alfred Marshall\'ın 1890\'da yayımlanan ve arz-talep çözümlemesini yaygınlaştıran eseri hangisidir?', 'Ekonominin İlkeleri', ['Ulusların Zenginliği', 'Kapital', 'Genel Teori'], 'Marshall\'ın "Principles of Economics" adlı eseri uzun yıllar temel ders kitabı olarak okutulmuştur.'),
  ('Bir hane halkının marketten süt alması döngüsel akım modelinde hangi piyasada gerçekleşir?', 'Mal piyasası', ['Faktör piyasası', 'Emek piyasası', 'Sermaye piyasası'], 'Hane halklarının firmalardan mal ve hizmet satın aldığı yer mal piyasasıdır.'),
  ('GSYH hesabında üretimin değeri genellikle hangi fiyatlarla ölçülür?', 'Piyasa fiyatlarıyla', ['Üretici tahminleriyle', 'Devletin belirlediği sabit puanlarla', 'Malların ağırlıklarıyla'], 'Farklı malları toplayabilmek için her mal piyasa fiyatıyla çarpılır ve değerler toplanır.'),
  ('Sanayi sektörünün temel işlevi nedir?', 'Hammaddeyi işleyerek yeni ürünlere dönüştürmek', ['Doğadan doğrudan ürün elde etmek', 'Yalnızca hizmet sunmak', 'Yalnızca dış ticaret yapmak'], 'İmalat ve inşaat gibi faaliyetlerle hammadde ve ara mallar işlenir; bu ikincil sektördür.'),
  ('İşbölümünün en belirgin sonucu aşağıdakilerden hangisidir?', 'Verimliliğin artması', ['Üretimin azalması', 'Maliyetlerin artması', 'İşsizliğin kesin olarak yükselmesi'], 'Her işçinin belirli bir işe odaklanması üretim hızını ve verimliliği artırır.'),
  ('Fırsat maliyeti kavramı hangi durumda ortaya çıkmaz?', 'Hiçbir seçimin gerekmediği durumda', ['Bir kaynak iki farklı işte kullanılabildiğinde', 'Zamanın sınırlı olduğu durumda', 'Bütçenin kısıtlı olduğu durumda'], 'Fırsat maliyeti seçimin sonucudur; kaynaklar kıt olmasaydı ve seçim gerekmeseydi vazgeçilen bir şey de olmazdı.'),
];
